// tests/e2e/audit/pathwayUniverse.ts
//
// THE SET OF PATHWAY IDS THE SPECS DEFINE, the third argument to `checkCoverageMap`
// (design, "Coverage_Map"). Two sources:
//
//   - `audit-artifacts/.pathways.json`, the output of `playwright test --list
//     --reporter=json` that `scripts/e2e/audit.mjs` writes before the run. Each
//     Pathway carries an `@id:<id>` tag generated by the DSL from its declaration.
//   - the `pathway({ id: '…' })` literals in `tests/e2e/specs/**`, read statically.
//     The unit guard over the real Coverage_Map uses this, and the `preflight`
//     project falls back to it when the list file has not been written (a bare
//     `npx playwright test` rather than `npm run audit`).
//
// The two parsers are pure; `readPathwayUniverse` does the file reading.

import { existsSync, readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';

/** Where `audit.mjs` writes the `--list --reporter=json` output, relative to the root. */
export const PATHWAYS_LIST_FILE = path.join('audit-artifacts', '.pathways.json');

/** Where the Pathway specs live, relative to the root. */
export const SPECS_DIR = path.join('tests', 'e2e', 'specs');

const ID_TAG = /(?<![\w@])@id:([^\s,'"`]+)/g;
const PATHWAY_LITERAL = /\bpathway\(\s*\{\s*id:\s*(['"`])([^'"`\n]+)\1/g;

/**
 * Pathway ids from a Playwright JSON list report: every `@id:<id>` found in a spec's
 * `tags` or in a title, anywhere in the suite tree. Sorted and de-duplicated, because
 * one Pathway is listed once per project. Throws on text that is not JSON rather than
 * returning an empty universe.
 */
export function pathwayIdsFromListJson(json: string): string[] {
  const ids = new Set<string>();
  const collect = (text: string): void => {
    for (const match of text.matchAll(ID_TAG)) ids.add(match[1]);
  };
  const walk = (node: unknown): void => {
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    if (node === null || typeof node !== 'object') return;
    const record = node as Record<string, unknown>;
    if (Array.isArray(record.tags)) {
      for (const tag of record.tags) if (typeof tag === 'string') collect(tag.startsWith('@') ? tag : `@${tag}`);
    }
    if (typeof record.title === 'string') collect(record.title);
    for (const [key, value] of Object.entries(record)) {
      if (key !== 'tags' && key !== 'title') walk(value);
    }
  };
  walk(JSON.parse(json) as unknown);
  return [...ids].sort();
}

/** Pathway ids declared by `pathway({ id: '…' })` literals in one source file. */
export function pathwayIdsFromSource(source: string): string[] {
  return [...source.matchAll(PATHWAY_LITERAL)].map((match) => match[2]);
}

function specFiles(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return specFiles(full);
    return /\.tsx?$/.test(entry.name) ? [full] : [];
  });
}

/** Every Pathway id declared in the specs' source, sorted and de-duplicated. */
export function pathwayIdsInSpecs(root: string = process.cwd()): string[] {
  const ids = new Set<string>();
  for (const file of specFiles(path.join(root, SPECS_DIR))) {
    for (const id of pathwayIdsFromSource(readFileSync(file, 'utf8'))) ids.add(id);
  }
  return [...ids].sort();
}

/** The Pathway universe and where it came from. */
export interface PathwayUniverse {
  ids: string[];
  source: 'list-file' | 'spec-source';
}

/**
 * The defined Pathway ids: the list file when `audit.mjs` wrote one, else the static
 * scan of the specs. The source is returned so the caller can say which it used.
 */
export function readPathwayUniverse(root: string = process.cwd()): PathwayUniverse {
  const file = path.join(root, PATHWAYS_LIST_FILE);
  if (existsSync(file)) {
    return { ids: pathwayIdsFromListJson(readFileSync(file, 'utf8')), source: 'list-file' };
  }
  return { ids: pathwayIdsInSpecs(root), source: 'spec-source' };
}
